beforeExample:
import java.util.Objects;
class StringMatcher {
    StringMatcher(String p, boolean b1, boolean b2) {}
}

public class Example {
    private StringMatcher createStringMatcher(String filterText) {
        filterText = Objects.requireNonNull(filterText).trim(); // Assume filterText is non-null before trim()
        if (filterText != null && filterText.length() > 0) {
            return new StringMatcher("*" + filterText + "*", true, false);
        }
        return null;
    }
}

